13	// Clear removes cache files from the cache directory.
14	//
15	// If force is true, the entire cache directory is removed.
16	// If force is false, only cache files older than 7 days that match certain patterns are deleted.
17	// The excludedFiles parameter allows you to specify file names that should not be deleted,
18	// even if they would otherwise be eligible for removal.
19	func Clear(force bool, excludedFiles ...string) error {
20		defer log.Trace(time.Now())
21	
22		if force {
23			return os.RemoveAll(Path())
24		}
25	
26		// get all files in the cache directory that start with omp.cache and delete them
27		files, err := os.ReadDir(Path())
28		if err != nil {
29			return err
30		}
31	
32		// get all log files as well
33		if logFiles, err := os.ReadDir(filepath.Join(Path(), "logs")); err == nil {
34			files = append(files, logFiles...)
35		}
36	
37		shouldSkip := func(fileName string) bool {
38			if slices.Contains(excludedFiles, fileName) {
39				return true
40			}
41	
42			return strings.EqualFold(fileName, DeviceStore) || strings.HasPrefix(fileName, "init.")
43		}
44	
45		if len(excludedFiles) > 0 {
46			log.Debug("excluding files from deletion:", strings.Join(excludedFiles, ", "))
47		}
48	
49		deleteFile := func(file string) {
50			path := filepath.Join(Path(), file)
51			err := os.Remove(path)
52			if err != nil {
53				log.Error(err)
54				return
55			}
56	
57			log.Debugf("removed cache file: %s", path)
58		}
59	
60		cacheTTL := GetTTL()
61	
62		log.Debugf("removing cache files older than %d days", cacheTTL)
63	
64		for _, file := range files {
65			if file.IsDir() {
66				continue
67			}
68	
69			if shouldSkip(file.Name()) {
70				log.Debug("skipping excluded file:", file.Name())
71				continue
72			}
73	
74			cacheFileInfo, err := file.Info()
75			if err != nil {
76				log.Debug("skipping file, cannot get info:", file.Name())
77				continue
78			}
79	
80			if cacheFileInfo.ModTime().After(time.Now().AddDate(0, 0, -cacheTTL)) {
81				log.Debug("skipping recently used file:", file.Name())
82				continue
83			}
84	
85			deleteFile(file.Name())
86		}
87	
88		return nil
89	}
