13	type persistentStringRWCloser struct {
14		pss      *PersistentSharedString
15		buf      *bytes.Buffer
16		filePath string
17		dirty    bool
18	}
19	
20	func NewPersistentStringRWCloser(pss *PersistentSharedString) io.ReadWriteCloser {
21		return &persistentStringRWCloser{
22			pss:      pss,
23			buf:      bytes.NewBuffer(pss.bytes()),
24			filePath: pss.filePath,
25		}
26	}
