41	func (rw *persistentStringRWCloser) Close() error {
42		defer rw.pss.close()
43	
44		if !rw.dirty {
45			return nil
46		}
47	
48		data := rw.buf.String()
49		dataSize := len(data)
50	
51		// Check if the data fits in the current allocation
52		if dataSize <= rw.pss.size {
53			return rw.pss.SetString(data)
54		}
55	
56		// Data is too large, need to recreate with larger size
57		log.Debugf("cache data size (%d) exceeds current allocation (%d), recreating file", dataSize, rw.pss.size)
58	
59		// Calculate new size with some growth factor (1.5x) to reduce future reallocations
60		newSize := max(dataSize+(dataSize/2), minStringSize)
61		if newSize > maxStringSize {
62			return fmt.Errorf("required cache size %d exceeds maximum %d", dataSize, maxStringSize)
63		}
64	
65		// Close current mapping before recreating
66		if err := rw.pss.close(); err != nil {
67			log.Error(err)
68		}
69	
70		// Create new file with larger size
71		newPss, err := createOrOpenPersistentStringWithSize(rw.filePath, newSize)
72		if err != nil {
73			return fmt.Errorf("failed to recreate cache file with size %d: %v", newSize, err)
74		}
75	
76		// Write the data to the new file
77		return newPss.SetString(data)
78	}
